// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5)
//
// Two-LED + button demo:
//   * GPIO4 -> 220R -> LED1 (red)   -> GND
//   * GPIO5 -> 220R -> LED2 (green) -> GND
//   * GPIO3 -> button -> GND, internal pull-up enabled (pressed = LOW)
//
// Behaviour: while the button is held down both LEDs are lit; when it is
// released both LEDs are dark. Plain GPIO on/off levels only (no PWM,
// no interrupts, no peripherals that the simulator does not model).
// The button is polled every 10 ms, so the LEDs follow the button state
// with <= ~10 ms latency and always in perfect sync with each other.

#include <stdio.h>
#include <stdbool.h>

#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"

#define LED1_GPIO   GPIO_NUM_4   /* red LED   */
#define LED2_GPIO   GPIO_NUM_5   /* green LED */
#define BTN_GPIO    GPIO_NUM_3   /* push button, active low */

#define POLL_MS     10           /* button polling period */

void app_main(void)
{
    /* --- outputs: both LEDs off at reset ---------------------------------- */
    gpio_config_t out_cfg = {
        .pin_bit_mask = (1ULL << LED1_GPIO) | (1ULL << LED2_GPIO),
        .mode         = GPIO_MODE_OUTPUT,
        .pull_up_en   = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    gpio_config(&out_cfg);
    gpio_set_level(LED1_GPIO, 0);
    gpio_set_level(LED2_GPIO, 0);

    /* --- input: button with internal pull-up (pressed = LOW) -------------- */
    gpio_config_t in_cfg = {
        .pin_bit_mask = (1ULL << BTN_GPIO),
        .mode         = GPIO_MODE_INPUT,
        .pull_up_en   = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    gpio_config(&in_cfg);

    printf("PlugAI: 2 LEDs + button (GPIO4/GPIO5 LEDs, GPIO3 button, active low)\n");
    printf("BTN released: LEDs OFF\n");

    bool last_pressed = false;

    while (1) {
        bool pressed = (gpio_get_level(BTN_GPIO) == 0);

        if (pressed != last_pressed) {
            last_pressed = pressed;
            printf(pressed ? "BTN pressed: LEDs ON\n"
                           : "BTN released: LEDs OFF\n");
        }

        /* Both LEDs always in sync, follow the current button state. */
        gpio_set_level(LED1_GPIO, pressed ? 1 : 0);
        gpio_set_level(LED2_GPIO, pressed ? 1 : 0);

        vTaskDelay(pdMS_TO_TICKS(POLL_MS));
    }
}
